(5786515, 841709, 108525, '<td valign="top">none of the umbrellas seem to be in sharp focus</td>', 'none of the umbrellas seem to be in sharp focus', '2009-12-30 01:32:52.000000', NULL, 1),
(5786517, 842819, 108525, '<td valign="top">i think I would have went with a green (or almost any other color) umbrella.  Green would have "popped" off the page, the red just blends in too much and you lose sight of the intended subject.</td>', 'i think I would have went with a green (or almost any other color) umbrella.  Green would have "popped" off the page, the red just blends in too much and you lose sight of the intended subject.', '2009-12-30 01:35:13.000000', NULL, 1),
