(5786530, 842787, 102024, '<td valign="top">That''s a lovely tree.  I think the high-contrast works well for this image.</td>', 'That''s a lovely tree.  I think the high-contrast works well for this image.', '2009-12-30 01:45:46.000000', NULL, 1),
(5786531, 842757, 102024, '<td valign="top">The lines and shapes are so defined and geometric, yet there is a very off-balance, unorderly sort of feel to this image that sort of bothers me.</td>', 'The lines and shapes are so defined and geometric, yet there is a very off-balance, unorderly sort of feel to this image that sort of bothers me.', '2009-12-30 01:46:59.000000', NULL, 1),
