(5794851, 842628, 82534, '<td valign="top">Interesting scene, but the umbrellas don''t grab my attention, and they appear to be out of focus.</td>', 'Interesting scene, but the umbrellas don''t grab my attention, and they appear to be out of focus.', '2010-01-04 08:44:10.000000', NULL, 1),
