(5796860, 842483, 96751, '<td valign="top">Love the composition, but the color is a bit washed out for me, and the focus a bit too soft.</td>', 'Love the composition, but the color is a bit washed out for me, and the focus a bit too soft.', '2010-01-05 11:34:58.000000', NULL, 1),
