(5796871, 842705, 96751, '<td valign="top">Great idea, very surreal.  I would have preferred more lighting all around, though, as it would have made more of the image "pop".</td>', 'Great idea, very surreal.  I would have preferred more lighting all around, though, as it would have made more of the image "pop".', '2010-01-05 11:37:28.000000', NULL, 1),
(5796874, 841829, 93756, '<td valign="top">Really cool scene - perfect for this challenge of course. I don''t care for your angle. I think a straight-on shot would have been better so you didn''t cut off the front umbrella. You could have cropped out the busyness on the right side so we focus on your subject more.</td>', 'Really cool scene - perfect for this challenge of course. I don''t care for your angle. I think a straight-on shot would have been better so you didn''t cut off the front umbrella. You could have cropped out the busyness on the right side so we focus on your subject more.', '2010-01-05 11:40:16.000000', NULL, 1),
(5796875, 842820, 93756, '<td valign="top">Blurring the background by using a lower depth of field would improve your image. The reflection is very cool and you don''t want the background clutter to detract from it. Cropping would give you a neat abstract.</td>', 'Blurring the background by using a lower depth of field would improve your image. The reflection is very cool and you don''t want the background clutter to detract from it. Cropping would give you a neat abstract.', '2010-01-05 11:40:32.000000', NULL, 1),
(5796881, 842487, 96751, '<td valign="top">LOVE this!  Very surreal, great detail on the umbrellas; excellent choice for b/w; the mist (and sniffing dog) perfect mood enhancers.</td>', 'LOVE this!  Very surreal, great detail on the umbrellas; excellent choice for b/w; the mist (and sniffing dog) perfect mood enhancers.', '2010-01-05 11:44:39.000000', NULL, 1),
(5796883, 842819, 96751, '<td valign="top">I love the forest/trail shot, although the color seems oversaturated, and the umbrella contrived.</td>', 'I love the forest/trail shot, although the color seems oversaturated, and the umbrella contrived.', '2010-01-05 11:45:15.000000', NULL, 1),
(5796884, 842018, 96751, '<td valign="top">I think the overly-bright background does this shot a disservice.</td>', 'I think the overly-bright background does this shot a disservice.', '2010-01-05 11:46:12.000000', NULL, 1),
